begin;
select plan(11);
create function pg_temp.as_user(uid uuid) returns void language sql as $$ select set_config('role','authenticated',true),set_config('request.jwt.claims',json_build_object('sub',uid,'role','authenticated')::text,true); $$;
insert into auth.users(id,email) values('a3333333-0000-0000-0000-000000000001','webpush-a@example.com');
update public.profiles set handle='webpush_a' where id='a3333333-0000-0000-0000-000000000001';
select pg_temp.as_user('a3333333-0000-0000-0000-000000000001');
select throws_ok($$select public.register_browser_push('13333333-0000-0000-0000-000000000001','23333333-0000-0000-0000-000000000001','https://fcm.googleapis.com/test',repeat('a',87),repeat('b',22),'desktop')$$,'22023',null,'desktop platform rejected');
select throws_ok($$select public.register_browser_push('13333333-0000-0000-0000-000000000001','23333333-0000-0000-0000-000000000001','https://fcm.googleapis.com/test',repeat('a',87),repeat('b',22),null)$$,'22023',null,'explicit mobile platform required');
select throws_ok($$select public.register_browser_push('13333333-0000-0000-0000-000000000001','23333333-0000-0000-0000-000000000001','https://127.0.0.1/private',repeat('a',87),repeat('b',22),'android')$$,'22023',null,'SSRF endpoint rejected');
select throws_ok($$select public.register_browser_push('13333333-0000-0000-0000-000000000001','23333333-0000-0000-0000-000000000001','https://web.push.apple.com/test','invalid',repeat('b',22),'ios_home_screen')$$,'22023',null,'malformed key rejected');
select lives_ok($$select public.register_browser_push('13333333-0000-0000-0000-000000000001','23333333-0000-0000-0000-000000000001','https://web.push.apple.com/old',repeat('a',87),repeat('b',22),'ios_home_screen')$$,'authenticated Home Screen registration');
select public.register_browser_push('13333333-0000-0000-0000-000000000001','23333333-0000-0000-0000-000000000001','https://web.push.apple.com/new',repeat('a',87),repeat('b',22),'ios_home_screen');
set local role anon;
select public.remove_browser_push('13333333-0000-0000-0000-000000000001','23333333-0000-0000-0000-000000000001','https://web.push.apple.com/old');
reset role;
select is((select web_endpoint from public.push_destinations),'https://web.push.apple.com/new','old expiry cleanup preserves replacement subscription');
set local role anon;
select public.remove_browser_push('13333333-0000-0000-0000-000000000001','23333333-0000-0000-0000-000000000001','https://web.push.apple.com/new');
reset role;
select is((select count(*)::int from public.push_destinations),0,'expiry cleanup works without authenticated session');
select pg_temp.as_user('a3333333-0000-0000-0000-000000000001');
select lives_ok($$select public.register_browser_push('13333333-0000-0000-0000-000000000001','23333333-0000-0000-0000-000000000001','https://fcm.googleapis.com/android',repeat('a',87),repeat('b',22),'android')$$,'authenticated Android registration');
select throws_ok($$insert into public.follows(follower_id,followee_id,notification_generation) values(auth.uid(),'c3333333-0000-0000-0000-000000000001',gen_random_uuid())$$,'42501',null,'clients cannot forge follow source generations');
select throws_ok($$insert into public.entry_likes(entry_id,user_id,notification_generation) values('e3333333-0000-0000-0000-000000000001',auth.uid(),gen_random_uuid())$$,'42501',null,'clients cannot forge like source generations');
select throws_ok($$update public.notification_policy set repeat_push_cooldown=interval '0'$$,'42501',null,'repeat-push policy remains server-owned');
select * from finish();
rollback;
